graph = {
    'a': ['b'],
    'b': ['a', 'c'],
    'c': ['b', 'd'],
    'd': ['c'],
}
regs = ['R1', 'R2']
color = {}
for v in graph:
    used = {color[u] for u in graph[v] if u in color}
    for r in regs:
        if r not in used:
            color[v] = r
            break
print(color['a'], color['c'], color['b'], color['d'])
